div.script:
(function(){
  // Scroll reveal
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(e.isIntersecting){ e.target.classList.add('oc_in'); io.unobserve(e.target); }
    });
  },{threshold:0.1,rootMargin:'0px 0px -40px 0px'});
  document.querySelectorAll('.oc_reveal,.oc_reveal_r').forEach(function(el){ io.observe(el); });

  // Dashboard 3D tilt
  var frame = document.querySelector('.oc_dash_frame');
  if(frame){
    frame.addEventListener('mousemove',function(e){
      var r = this.getBoundingClientRect();
      var x = (e.clientX - r.left)/r.width - 0.5;
      var y = (e.clientY - r.top)/r.height - 0.5;
      this.style.transform = 'perspective(1200px) rotateY('+(x*10)+'deg) rotateX('+(-y*5)+'deg) scale(1)';
    });
    frame.addEventListener('mouseleave',function(){
      this.style.transform = 'perspective(1200px) rotateY(-6deg) rotateX(3deg) scale(.97)';
    });
  }

  // Animated stat counters
  var counters = document.querySelectorAll('.oc_counter_n');
  var counterIO = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(!entry.isIntersecting) return;
      counterIO.unobserve(entry.target);
      var el = entry.target;
      var target = parseFloat(el.getAttribute('data-target'));
      var decimals = parseInt(el.getAttribute('data-decimals') || '0', 10);
      var suffix = el.getAttribute('data-suffix') || '';
      var duration = 1400;
      var start = null;
      function step(ts){
        if(!start) start = ts;
        var progress = Math.min((ts - start) / duration, 1);
        var eased = 1 - Math.pow(1 - progress, 3);
        el.textContent = (target * eased).toFixed(decimals) + suffix;
        if(progress < 1){ requestAnimationFrame(step); }
      }
      requestAnimationFrame(step);
    });
  },{threshold:0.4});
  counters.forEach(function(el){ counterIO.observe(el); });

  // FAQ accordion
  document.querySelectorAll('.oc_faq_q').forEach(function(btn){
    btn.addEventListener('click', function(){
      var item = this.closest('.oc_faq_item');
      var wasOpen = item.classList.contains('oc_open');
      document.querySelectorAll('.oc_faq_item.oc_open').forEach(function(i){ i.classList.remove('oc_open'); });
      if(!wasOpen){ item.classList.add('oc_open'); }
    });
  });

  // Smooth scroll for anchor links (offset 68px for fixed nav)
  document.querySelectorAll('.oc_page a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var id = this.getAttribute('href').slice(1);
      var el = document.getElementById(id);
      if(el){
        e.preventDefault();
        var top = el.getBoundingClientRect().top + window.scrollY - 72;
        window.scrollTo({top:top,behavior:'smooth'});
      }
    });
  });
})();
